//! Every construction against ZisK's own implementation ([`super::zisk_kat`],
//! generated by `scripts/poseidon1/zisk_crosscheck` from pil2-proofman's
//! `proofman-fields`), and the checks that make the vectors bind.

use alloc::vec::Vec;

use super::zisk_kat::{
    GRIND_BITS, GRIND_LANE0, GRIND_SMALLEST_NONCE, LINEAR_HASH, MERKLE4_ROOTS, PATH_ROOT,
    PATH_ROWS, PATH_WIDTH, PATHS, PERM8, PERM16, SEED_GRIND, SEED_LEAF, SEED_ROWS, SEED_TRANSCRIPT,
    SEED_TREE, TRANSCRIPT_OUT, TRANSCRIPT_QUERIES,
};
use super::*;

const P: u64 = 0xFFFF_FFFF_0000_0001;

/// The generator's LCG (`p1_params.py kat_inputs`), reduced mod `p`.
pub(super) fn felts(seed: u64, n: usize) -> Vec<Fp> {
    let mut x = seed;
    (0..n)
        .map(|_| {
            x = x
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            Fp::from(x % P)
        })
        .collect()
}

fn canon(v: &[Fp]) -> Vec<u64> {
    v.iter().map(|f| f.canonical()).collect()
}

fn digests(seed: u64, n: usize) -> Vec<Digest> {
    felts(seed, 4 * n)
        .chunks_exact(4)
        .map(|c| [c[0], c[1], c[2], c[3]])
        .collect()
}

#[test]
fn the_width_16_permutation_is_zisks() {
    for (input, expected) in PERM16.iter() {
        let s = core::array::from_fn(|i| Fp::from(input[i]));
        assert_eq!(canon(&permute(s)), expected.to_vec());
    }
}

#[test]
fn the_width_8_permutation_is_zisks() {
    for (input, expected) in PERM8.iter() {
        let s = core::array::from_fn(|i| Fp::from(input[i]));
        assert_eq!(canon(&poseidon1_w8::permute(s)), expected.to_vec());
    }
}

#[test]
fn the_leaf_hash_is_zisks() {
    for (len, expected) in LINEAR_HASH.iter() {
        assert_eq!(
            canon(&linear_hash(&felts(SEED_LEAF, *len))),
            expected.to_vec(),
            "len {len}"
        );
    }
}

#[test]
fn the_leaf_vectors_pin_the_digest_carry() {
    // Mutation: a textbook sponge carries the capacity lanes 12..16 between
    // blocks; ZisK carries the digest lanes 0..4 into them. Every multi-block
    // vector must tell the two apart, and every one-block vector must not.
    let sponge = |felts: &[Fp]| {
        let mut state = [Fp::zero(); WIDTH];
        for block in felts.chunks(RATE) {
            state[..RATE].fill(Fp::zero());
            state[..block.len()].copy_from_slice(block);
            state = permute(state);
        }
        [state[0], state[1], state[2], state[3]]
    };
    let mut multi = 0;
    for (len, expected) in LINEAR_HASH.iter() {
        let differs = canon(&sponge(&felts(SEED_LEAF, *len))) != expected.to_vec();
        assert_eq!(differs, *len > RATE, "len {len}");
        multi += usize::from(*len > RATE);
    }
    assert!(multi >= 5, "too few multi-block vectors: {multi}");
}

#[test]
fn the_tree_roots_are_zisks() {
    for (n, expected) in MERKLE4_ROOTS.iter() {
        let tree = Merkle4::new(&digests(SEED_TREE, *n)).expect("non-empty");
        assert_eq!(canon(&tree.root()), expected.to_vec(), "{n} leaves");
    }
    assert!(Merkle4::new(&[]).is_none());
}

#[test]
fn the_tree_vectors_pin_the_zero_padding() {
    // Mutation: padding a short level by repeating its last digest instead of
    // zero digests must change every root that pads.
    for (n, expected) in MERKLE4_ROOTS.iter() {
        let mut level = digests(SEED_TREE, *n);
        while level.len() > 1 {
            while !level.len().is_multiple_of(ARITY) {
                level.push(*level.last().expect("non-empty"));
            }
            level = level
                .chunks_exact(ARITY)
                .map(|c| compress4(&[c[0], c[1], c[2], c[3]]))
                .collect();
        }
        let no_padding = n.is_power_of_two() && n.trailing_zeros() % 2 == 0;
        assert_eq!(
            canon(&level[0]) == expected.to_vec(),
            no_padding,
            "{n} leaves"
        );
    }
}

#[test]
fn the_paths_are_zisks_and_verify() {
    let rows: Vec<Vec<Fp>> = felts(SEED_ROWS, PATH_ROWS * PATH_WIDTH)
        .chunks_exact(PATH_WIDTH)
        .map(<[Fp]>::to_vec)
        .collect();
    let leaves: Vec<Digest> = rows.iter().map(|r| linear_hash(r)).collect();
    let tree = Merkle4::new(&leaves).expect("non-empty");
    assert_eq!(canon(&tree.root()), PATH_ROOT.to_vec());
    let root = tree.root();
    for (index, expected) in PATHS.iter() {
        let path = tree.path(*index).expect("in range");
        assert_eq!(path.len(), expected.len());
        for (level, want) in path.iter().zip(expected.iter()) {
            assert_eq!(canon(level), want.to_vec(), "index {index}");
        }
        assert!(verify_path4(&root, &leaves[*index], *index, &path));
    }
}

#[test]
fn a_tampered_path_is_rejected() {
    let leaves = digests(SEED_TREE, 21);
    let tree = Merkle4::new(&leaves).expect("non-empty");
    let root = tree.root();
    for index in [0, 7, 20] {
        let path = tree.path(index).expect("in range");
        assert!(verify_path4(&root, &leaves[index], index, &path));
        for level in 0..path.len() {
            for felt in 0..SIBLING_FELTS {
                let mut bad = path.clone();
                bad[level][felt] += Fp::one();
                assert!(!verify_path4(&root, &leaves[index], index, &bad));
            }
        }
        let mut leaf = leaves[index];
        leaf[3] += Fp::one();
        assert!(!verify_path4(&root, &leaf, index, &path));
        // The same path cannot open a neighbouring index, nor one past the
        // tree that aliases this one modulo 4^depth.
        assert!(!verify_path4(&root, &leaves[index], index ^ 1, &path));
        let alias = index + ARITY.pow(tree.depth() as u32);
        assert!(!verify_path4(&root, &leaves[index], alias, &path));
        assert!(!verify_path4(&root, &leaves[index], index, &path[1..]));
    }
    assert!(tree.path(21).is_none());
}

#[test]
fn the_transcript_is_zisks() {
    let input = felts(SEED_TRANSCRIPT, 4 + 4 + 4 + 12 + 30);
    let (a, rest) = input.split_at(4);
    let (b, rest) = rest.split_at(4);
    let (c, rest) = rest.split_at(4);
    let (d, e) = rest.split_at(12);
    let mut t = Transcript::new();
    let mut out = Vec::new();
    t.put(a);
    t.put(b);
    out.extend(t.field());
    out.extend(t.field());
    t.put(c);
    out.extend(t.field());
    t.put(d);
    out.extend(t.field());
    t.put(e);
    for _ in 0..6 {
        out.extend(t.field());
    }
    out.extend(t.state());
    assert_eq!(canon(&out), TRANSCRIPT_OUT.to_vec());

    let last = &out[out.len() - 16 - 3..out.len() - 16];
    let mut q = Transcript::new();
    q.put(last);
    q.put1(Fp::from(12345u64));
    assert_eq!(q.indices(10, 21), TRANSCRIPT_QUERIES.to_vec());
}

#[test]
fn the_transcript_binds_every_absorbed_felt() {
    // Changing any one absorbed felt changes the first challenge squeezed.
    let input = felts(SEED_TRANSCRIPT, 30);
    let first = |xs: &[Fp]| {
        let mut t = Transcript::new();
        t.put(xs);
        t.field()
    };
    let honest = first(&input);
    for i in 0..input.len() {
        let mut bad = input.clone();
        bad[i] += Fp::one();
        assert_ne!(first(&bad), honest, "felt {i}");
    }
}

#[test]
fn the_grinding_hash_is_zisks() {
    let ch = felts(SEED_GRIND, 3);
    let ch = [ch[0], ch[1], ch[2]];
    for (nonce, lane0) in GRIND_LANE0.iter() {
        assert_eq!(grinding_lane0(&ch, &Fp::from(*nonce)), *lane0);
    }
    let smallest = (0u64..)
        .find(|n| grinding_ok(&ch, &Fp::from(*n), GRIND_BITS))
        .expect("a nonce exists");
    assert_eq!(smallest, GRIND_SMALLEST_NONCE);
    assert!(!grinding_ok(
        &ch,
        &Fp::from(GRIND_SMALLEST_NONCE - 1),
        GRIND_BITS
    ));
    assert!(grinding_ok(&ch, &Fp::from(0u64), 0));
    assert!(!grinding_ok(&ch, &Fp::from(GRIND_SMALLEST_NONCE), 64));
}
